import assert from 'node:assert/strict';
import { parse, generate } from '../../lib/index.js';

// A declaration value kept as a raw string (parseValue: false) must be
// serialized verbatim, without automatic whitespace between its tokens.
const ast = parse('a{border:1%var(--a)#ff0000}', { parseValue: false });
assert.equal(generate(ast), 'a{border:1%var(--a)#ff0000}');

// Parsed values still get the whitespace needed to keep tokens apart.
const parsed = parse('a{border:1%var(--a)#ff0000}');
assert.equal(generate(parsed), 'a{border:1% var(--a) #ff0000}');

console.log('visible check passed');

import * as chai from '../../index.js';
import assert from 'node:assert/strict';

chai.expect([[1], [2]]).to.deep.contain.oneOf([[1], [2]]);
chai.expect([[3], [4]]).to.not.deep.contain.oneOf([[1], [2]]);
assert.throws(() => chai.expect([[1]]).to.deep.contain.oneOf([[2]]));
chai.expect([1, 2]).to.contain.oneOf([4, 2, 5]);
chai.expect([[1]]).to.not.contain.oneOf([[1]]);

console.log('visible check passed');

import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { LRUCache } from '../../dist/esm/index.js';

const source = readFileSync(new URL('../../src/index.ts', import.meta.url), 'utf8');
const matches = source.match(/!this\.ttlAutopurge \?/g) ?? [];
assert.equal(matches.length, 1, 'expected exactly one `!this.ttlAutopurge ?` guard in src/index.ts');

const plain = new LRUCache({ max: 5, ttl: 1000, ttlAutopurge: false });
plain.set('a', 1);
assert.equal(plain.get('a'), 1);
const purging = new LRUCache({ max: 5, ttl: 1000, ttlAutopurge: true });
purging.set('b', 2);
assert.equal(purging.get('b'), 2);
purging.clear();

console.log('visible check passed');

import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';

const pkg = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8'));
assert.ok(['12.0.0', '^12.0.0'].includes(pkg.devDependencies.c8), pkg.devDependencies.c8);
const lock = JSON.parse(readFileSync(new URL('../../package-lock.json', import.meta.url), 'utf8'));
assert.equal(lock.packages['node_modules/c8'].version, '12.0.0');
assert.ok(['12.0.0', '^12.0.0'].includes(lock.packages[''].devDependencies.c8), lock.packages[''].devDependencies.c8);

console.log('visible check passed');
